import{z as s,x as i,o as A,c as d,q as n,j as r,D as B,d as t,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"托管与柜台","description":"","frontmatter":{"title":"托管与柜台","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-custody-counter.md","filePath":"quant/cn-custody-counter.md","lastUpdated":1791413859000}'),p={name:"quant/cn-custody-counter.md"};function u(c,E,D,F,C,m){const e=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="托管与柜台" tabindex="-1">托管与柜台 <a class="header-anchor" href="#托管与柜台" aria-label="Permalink to &quot;托管与柜台&quot;">​</a></h1><div class="epigraph"><p>策略机到交易所之间隔着柜台、报盘与清算三道关；制度约束在柜台被翻译成代码，被它拒绝的委托，先查自己的头寸口径，再怪系统。</p><footer>—— 据证券托管结算与券商经纪业务口径整理</footer></div><p><a href="/quant/cn-fund-constraints">上一课</a>把两类载体的约束清单列完；约束要落地，靠两块基础设施：托管与券商柜台。<a href="/quant/cn-tplus1">T+1 与回转交易约束</a>写过交易制度侧的 T+1，本课写它在运营链路上的落点：策略机到交易所之间隔着什么，日终净值谁复核，头寸时效卡在哪一步。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量化实盘有一类失败不在信号也不在执行，而在链路：柜台的前端检查否掉你以为合法的委托；托管划款晚于保证金追缴时限；多券商拆分后头寸碎片化，组合层面的敞口在两边各自越线。产品视角还有一层：估值核算与净值复核由托管人把关，估值口径与策略预期对不上，申赎与业绩报酬的计算都会歪——这些都在上线之后才暴露，代价最大。</p><p><span class="marginnote">术语翻译：「券商柜台」（PB 系统或集中交易系统）就是券商替你管账户、跑前端风控、并把委托报进交易所的系统——像门口的安检员：所有单先过它，头寸不够、越限、违反 T+1 规则的委托在这里直接被拦下，策略机根本接触不到交易所。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链路解剖。下单链：策略机 → 券商柜台（PB 或集中交易系统）→ 报盘 → 交易所；行情下行走专线；低延迟部署涉及托管机房与报备的联动（<a href="/quant/cn-colocation-rectify">主机托管清退与交易单元整改</a>），对外接口的协议规范见 <a href="/quant/fix-protocol">FIX 协议</a>。资产链：托管人（商业银行或券商）保管资产、复核估值、执行划款；份额登记与估值核算可外包。日终流程固定：成交与持仓对账、净值复核、头寸冻结——T+1 的可用资金与券以登记结算的清算结果为准，不以委托回执为准。多券商治理：主券商与辅券商的费率、券源、柜台能力分别谈判，但组合层必须有一个头寸汇总视图，风险限额在汇总层执行。</p>',8)),(A(),r(l,null,{default:B(()=>[o(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20STRAT%5B%22%E7%AD%96%E7%95%A5%E6%9C%BA%22%5D%20--%3E%20COUNTER%5B%22%E5%88%B8%E5%95%86%E6%9F%9C%E5%8F%B0%EF%BC%9A%E5%89%8D%E7%AB%AF%E6%A3%80%E6%9F%A5%22%5D%0A%20%20COUNTER%20--%3E%20FLOOR%5B%22%E6%8A%A5%E7%9B%98%22%5D%0A%20%20FLOOR%20--%3E%20EXCH%5B%22%E4%BA%A4%E6%98%93%E6%89%80%22%5D%0A%20%20EXCH%20--%3E%20FILL%5B%22%E6%88%90%E4%BA%A4%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20FILL%20--%3E%20COUNTER%0A%20%20CUST%5B%22%E6%89%98%E7%AE%A1%E4%BA%BA%EF%BC%9A%E4%BF%9D%E7%AE%A1%2F%E4%BC%B0%E5%80%BC%E5%A4%8D%E6%A0%B8%2F%E5%88%92%E6%AC%BE%22%5D%20--%3E%20NAV%5B%22%E6%97%A5%E7%BB%88%EF%BC%9A%E5%AF%B9%E8%B4%A6%2B%E5%87%80%E5%80%BC%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20FILL%20--%3E%20NAV%0A%20%20NAV%20--%3E%20POS%5B%22T%2B1%20%E5%8F%AF%E7%94%A8%E5%A4%B4%E5%AF%B8%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"柜台是约束的执行点而不是通道。T+1 可用性、涨跌停、提价规则、担保品折算，都在柜台的前端检查里变成代码；策略层绕不过它，也不该试图绕过——被拒绝的委托，要么是策略没算头寸时效，要么是测算用了错误的可用口径。托管复核是操作风险的最后防线：估值与净值由管理人算、托管人核，两边对上才出数。理解这一点，就会把清算数据当成系统里的一等数据源来接，而不是把当日委托回执当成最终头寸；多券商拆分的复杂度也就有边界——拆分换议价与券源，代价是汇总视图与对账成本。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"回测与实盘最隐蔽的一条缝：T+1 可用资金在回测里常写成「昨日收盘可知」，实盘以清算数据为准，节假日与清算异常日会晚到——依赖盘前精确头寸的策略要留现金缓冲。")],-1)),(A(),r(l,null,{default:B(()=>[o(e,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%88%B8%E5%95%86A%E5%A4%B4%E5%AF%B8%E4%B8%8E%E6%95%9E%E5%8F%A3%22%5D%20--%3E%20AGG%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E5%A4%B4%E5%AF%B8%E6%B1%87%E6%80%BB%E8%A7%86%E5%9B%BE%22%5D%0A%20%20B%5B%22%E5%88%B8%E5%95%86B%E5%A4%B4%E5%AF%B8%E4%B8%8E%E6%95%9E%E5%8F%A3%22%5D%20--%3E%20AGG%0A%20%20C%5B%22%E5%88%B8%E5%95%86C%E5%A4%B4%E5%AF%B8%E4%B8%8E%E6%95%9E%E5%8F%A3%22%5D%20--%3E%20AGG%0A%20%20AGG%20--%3E%20RISK%5B%22%E7%BB%84%E5%90%88%E9%99%90%E9%A2%9D%E6%A3%80%E6%9F%A5%EF%BC%9A%E8%A1%8C%E4%B8%9A%2F%E4%B8%AA%E8%82%A1%2F%E6%9D%A0%E6%9D%86%22%5D%0A%20%20RISK%20--%3E%7C%22%E6%B1%87%E6%80%BB%E5%B1%82%E8%B6%8A%E7%BA%BF%22%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%E6%96%B0%E5%8D%95%E6%88%96%E8%A6%81%E6%B1%82%E9%99%8D%E6%95%9E%E5%8F%A3%22%5D%0A%20%20RISK%20--%3E%7C%22%E5%8D%95%E5%88%B8%E5%95%86%E5%90%84%E8%87%AA%E7%9C%8B%E9%83%BD%E5%90%88%E8%A7%84%22%7C%20OK%5B%22%E6%B1%87%E6%80%BB%E5%90%88%E8%A7%84%EF%BC%8C%E6%AD%A3%E5%B8%B8%E4%BA%A4%E6%98%93%22%5D%0A%20%20FRAG%5B%22%E7%BC%BA%E6%B1%87%E6%80%BB%E8%A7%86%E5%9B%BE%EF%BC%9A%E4%B8%A4%E8%BE%B9%E5%90%84%E8%87%AA%E8%B6%8A%E7%BA%BF%22%5D%20-.%E5%8F%8D%E9%9D%A2%E6%A1%88%E4%BE%8B.-%20AGG%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">常见误区：初学者容易把「委托回执」或「成交回报」当成最终头寸。实际上 T+1 可用资金与可卖券以日终清算结果为准——当日回执只是过程状态。头寸口径用错一层，柜台的前端检查就会不断拒绝你以为合法的委托。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写绕开前端检查或柜台限额的技术手段；系统与券商选型不做商业推荐；估值核算的会计准则细节不在本课。</p><p><span class="marginnote">数字实例：假设盘中收到追保通知要求当日 13:00 前补足 50 万元，托管划款却因双人复核与大额支付批次 13:40 才到账。强平看的是「钱是否到账」，不是「你是否已发起划款」——这几小时的时差就足以触发强平，这正是「托管划款晚于保证金追缴时限」的具体形状。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实盘两条链：下单链（策略机-柜台-报盘）与资产链（托管-估值-划款）。</li><li>柜台是制度约束的代码化执行点，被拒委托优先查头寸口径。</li><li>日终以清算结果为准：对账、净值复核、头寸冻结固定成流程。</li><li>多券商拆分换议价与券源，代价是必须建组合层头寸汇总视图。</li><li>出处：托管与结算业务制度口径；交易制度侧见<a href="/quant/cn-tplus1">T+1 与回转交易约束</a>。</li></ul>',6))])}const h=s(p,[["render",u]]);export{f as __pageData,h as default};
